import{_ as t,c as n,o as s,ag as e}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Globala vs lokala taggar","description":"","frontmatter":{},"headers":[],"relativePath":"05-taggar/globala-lokala.md","filePath":"05-taggar/globala-lokala.md","lastUpdated":1768462574000}'),l={name:"05-taggar/globala-lokala.md"};function r(o,a,i,p,d,g){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="globala-vs-lokala-taggar" tabindex="-1">Globala vs lokala taggar <a class="header-anchor" href="#globala-vs-lokala-taggar" aria-label="Permalink to &quot;Globala vs lokala taggar&quot;">​</a></h1><p>I TIA Portal använder du <strong>taggar</strong> (variabler) för att lagra data och kommunicera mellan olika delar av programmet. Att förstå skillnaden mellan globala och lokala taggar är avgörande för att strukturera ditt program korrekt och effektivt.</p><h2 id="vad-ar-taggar" tabindex="-1">Vad är taggar? <a class="header-anchor" href="#vad-ar-taggar" aria-label="Permalink to &quot;Vad är taggar?&quot;">​</a></h2><p>Taggar är <strong>symboliska namn</strong> för minnesområden i PLC:n. Istället för att skriva <code>%M0.0</code> kan du använda <code>Motor_Start</code>, vilket gör koden mer läsbar och lättare att underhålla.</p><h3 id="fordelar-med-taggar" tabindex="-1">Fördelar med taggar: <a class="header-anchor" href="#fordelar-med-taggar" aria-label="Permalink to &quot;Fördelar med taggar:&quot;">​</a></h3><ul><li>✅ <strong>Läsbarhet</strong> - <code>Temperature_Sensor</code> är tydligare än <code>%IW64</code></li><li>✅ <strong>Underhåll</strong> - Ändra adress på ett ställe, uppdateras överallt</li><li>✅ <strong>Dokumentation</strong> - Automatisk beskrivning av vad variabler gör</li><li>✅ <strong>HMI-integration</strong> - Samma taggar delas mellan PLC och HMI</li></ul><h2 id="globala-taggar-plc-tags" tabindex="-1">Globala taggar (PLC Tags) <a class="header-anchor" href="#globala-taggar-plc-tags" aria-label="Permalink to &quot;Globala taggar (PLC Tags)&quot;">​</a></h2><h3 id="vad-ar-globala-taggar" tabindex="-1">Vad är globala taggar? <a class="header-anchor" href="#vad-ar-globala-taggar" aria-label="Permalink to &quot;Vad är globala taggar?&quot;">​</a></h3><p>Globala taggar definieras i <strong>PLC tag table</strong> och är tillgängliga <strong>överallt</strong> i programmet - från alla OB, FB, FC och HMI.</p><h3 id="var-hittar-du-dem" tabindex="-1">Var hittar du dem? <a class="header-anchor" href="#var-hittar-du-dem" aria-label="Permalink to &quot;Var hittar du dem?&quot;">​</a></h3><ol><li>I projektträdet: <strong>PLC tags</strong> → <strong>Default tag table</strong></li><li>Du kan skapa flera tag tables för organisation</li></ol><h3 id="anvandningsomraden" tabindex="-1">Användningsområden <a class="header-anchor" href="#anvandningsomraden" aria-label="Permalink to &quot;Användningsområden&quot;">​</a></h3><p>✅ <strong>Använd globala taggar för:</strong></p><ul><li>In- och utgångar (<code>%I</code>, <code>%Q</code>) - fysiska sensorer och aktuatorer</li><li>Systemvariabler som delas mellan flera block</li><li>HMI-kommunikation (taggar som visas på operatörspanelen)</li><li>Variabler som flera FB/FC behöver läsa/skriva</li></ul><h3 id="exempel-global-tag-table" tabindex="-1">Exempel: Global tag table <a class="header-anchor" href="#exempel-global-tag-table" aria-label="Permalink to &quot;Exempel: Global tag table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Namn</th><th>Datatyp</th><th>Adress</th><th>Kommentar</th></tr></thead><tbody><tr><td><code>Start_Button</code></td><td>BOOL</td><td>%I0.0</td><td>Startknapp på panelen</td></tr><tr><td><code>Motor_Output</code></td><td>BOOL</td><td>%Q0.0</td><td>Motorutgång</td></tr><tr><td><code>Temperature_Sensor</code></td><td>INT</td><td>%IW64</td><td>Temperaturgivare (0-1000°C)</td></tr><tr><td><code>System_Running</code></td><td>BOOL</td><td>%M0.0</td><td>Systemstatus</td></tr><tr><td><code>Alarm_Active</code></td><td>BOOL</td><td>%M0.1</td><td>Aktivt larm</td></tr></tbody></table><h3 id="skapa-global-tagg" tabindex="-1">Skapa global tagg <a class="header-anchor" href="#skapa-global-tagg" aria-label="Permalink to &quot;Skapa global tagg&quot;">​</a></h3><ol><li>Öppna <strong>PLC tags</strong> → <strong>Default tag table</strong></li><li>Klicka i en tom rad</li><li>Fyll i: <ul><li><strong>Name:</strong> <code>Motor_Speed_Setpoint</code></li><li><strong>Data type:</strong> <code>INT</code></li><li><strong>Address:</strong> Låt TIA Portal tilldela automatiskt (eller ange manuellt)</li><li><strong>Comment:</strong> &quot;Motorhastighet 0-100%&quot;</li></ul></li><li>Spara med <code>Ctrl+S</code></li></ol><h2 id="lokala-taggar-local-tags" tabindex="-1">Lokala taggar (Local Tags) <a class="header-anchor" href="#lokala-taggar-local-tags" aria-label="Permalink to &quot;Lokala taggar (Local Tags)&quot;">​</a></h2><h3 id="vad-ar-lokala-taggar" tabindex="-1">Vad är lokala taggar? <a class="header-anchor" href="#vad-ar-lokala-taggar" aria-label="Permalink to &quot;Vad är lokala taggar?&quot;">​</a></h3><p>Lokala taggar definieras <strong>inuti</strong> en FB, FC eller OB och är <strong>endast tillgängliga</strong> inom det blocket. De försvinner när blocket inte körs (för temp-variabler).</p><h3 id="typer-av-lokala-taggar" tabindex="-1">Typer av lokala taggar <a class="header-anchor" href="#typer-av-lokala-taggar" aria-label="Permalink to &quot;Typer av lokala taggar&quot;">​</a></h3><h4 id="_1-input-in" tabindex="-1">1. Input (IN) <a class="header-anchor" href="#_1-input-in" aria-label="Permalink to &quot;1. Input (IN)&quot;">​</a></h4><p>Parametrar som <strong>skickas in</strong> till blocket.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FUNCTION_BLOCK &quot;FB_Motor&quot;</span></span>
<span class="line"><span>VAR_INPUT</span></span>
<span class="line"><span>    Start : BOOL;      // Kommer från anropande block</span></span>
<span class="line"><span>    Speed : INT;       // Önskad hastighet</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><h4 id="_2-output-out" tabindex="-1">2. Output (OUT) <a class="header-anchor" href="#_2-output-out" aria-label="Permalink to &quot;2. Output (OUT)&quot;">​</a></h4><p>Resultat som <strong>returneras</strong> från blocket.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VAR_OUTPUT</span></span>
<span class="line"><span>    Running : BOOL;    // Motorstatus</span></span>
<span class="line"><span>    Fault : BOOL;      // Felindikering</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><h4 id="_3-inout" tabindex="-1">3. InOut <a class="header-anchor" href="#_3-inout" aria-label="Permalink to &quot;3. InOut&quot;">​</a></h4><p>Parametrar som både läses och skrivas (pass-by-reference).</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VAR_IN_OUT</span></span>
<span class="line"><span>    Counter : INT;     // Räknare som uppdateras</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><h4 id="_4-static-fb-endast" tabindex="-1">4. Static (FB endast) <a class="header-anchor" href="#_4-static-fb-endast" aria-label="Permalink to &quot;4. Static (FB endast)&quot;">​</a></h4><p>Variabler som <strong>behåller sitt värde</strong> mellan anrop - fungerar som &quot;minne&quot; i FB.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VAR</span></span>
<span class="line"><span>    OldValue : INT;    // Sparat värde från förra cykeln</span></span>
<span class="line"><span>    Timer : TON;       // Timer behåller status</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><h4 id="_5-temp-temporary" tabindex="-1">5. Temp (Temporary) <a class="header-anchor" href="#_5-temp-temporary" aria-label="Permalink to &quot;5. Temp (Temporary)&quot;">​</a></h4><p>Temporäre hjälpvariabler som <strong>återställs</strong> varje cykel.</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VAR_TEMP</span></span>
<span class="line"><span>    Result : REAL;     // Mellanresultat i beräkning</span></span>
<span class="line"><span>    Index : INT;       // Loop-räknare</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><h2 id="globala-vs-lokala-nar-anvander-du-vad" tabindex="-1">Globala vs Lokala - När använder du vad? <a class="header-anchor" href="#globala-vs-lokala-nar-anvander-du-vad" aria-label="Permalink to &quot;Globala vs Lokala - När använder du vad?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspekt</th><th>Globala taggar</th><th>Lokala taggar</th></tr></thead><tbody><tr><td><strong>Omfattning</strong></td><td>Hela programmet</td><td>Endast inom blocket</td></tr><tr><td><strong>Livstid</strong></td><td>Permanent</td><td>Static: permanent, Temp: per cykel</td></tr><tr><td><strong>Minnesanvändning</strong></td><td>Alltid allokerat</td><td>Delas mellan block (temp)</td></tr><tr><td><strong>HMI-åtkomst</strong></td><td>Ja</td><td>Nej (måste exponeras via FB-instans)</td></tr><tr><td><strong>Användning</strong></td><td>I/O, systemvariabler, HMI</td><td>Intern logik, parametrar</td></tr></tbody></table><h2 id="praktiskt-exempel" tabindex="-1">Praktiskt exempel <a class="header-anchor" href="#praktiskt-exempel" aria-label="Permalink to &quot;Praktiskt exempel&quot;">​</a></h2><h3 id="scenario-motorstyrning" tabindex="-1">Scenario: Motorstyrning <a class="header-anchor" href="#scenario-motorstyrning" aria-label="Permalink to &quot;Scenario: Motorstyrning&quot;">​</a></h3><p><strong>Globala taggar (PLC tags):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start_Button    BOOL  %I0.0   &quot;Fysisk startknapp&quot;</span></span>
<span class="line"><span>Motor_Contactor BOOL  %Q0.0   &quot;Motorutgång&quot;</span></span>
<span class="line"><span>Emergency_Stop  BOOL  %I0.1   &quot;Nödstopp&quot;</span></span></code></pre></div><p><strong>FB &quot;Motor_Control&quot; med lokala taggar:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FUNCTION_BLOCK &quot;Motor_Control&quot;</span></span>
<span class="line"><span>VAR_INPUT</span></span>
<span class="line"><span>    Enable : BOOL;         // IN: Tillåt körning</span></span>
<span class="line"><span>    SpeedSetpoint : INT;   // IN: Önskad hastighet (0-100%)</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR_OUTPUT</span></span>
<span class="line"><span>    Running : BOOL;        // OUT: Motor igång</span></span>
<span class="line"><span>    ActualSpeed : INT;     // OUT: Verklig hastighet</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR</span></span>
<span class="line"><span>    StartTimer : TON;      // Static: Timer för mjukstart</span></span>
<span class="line"><span>    State : INT;           // Static: Tillståndsmaskin</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR_TEMP</span></span>
<span class="line"><span>    CalcSpeed : REAL;      // Temp: Beräkningshjälp</span></span>
<span class="line"><span>END_VAR</span></span></code></pre></div><p><strong>Anrop i OB1:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Instans av FB (med Static-minne)</span></span>
<span class="line"><span>&quot;Motor_DB&quot;(</span></span>
<span class="line"><span>    Enable := &quot;Start_Button&quot; AND NOT &quot;Emergency_Stop&quot;,</span></span>
<span class="line"><span>    SpeedSetpoint := 75,</span></span>
<span class="line"><span>    Running =&gt; &quot;Motor_Contactor&quot;</span></span>
<span class="line"><span>);</span></span></code></pre></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rekommendationer</p><ol><li><strong>Globala taggar:</strong> Endast för I/O, HMI och variabler som måste delas brett</li><li><strong>Lokala taggar:</strong> All intern logik i FB/FC</li><li><strong>Namnkonvention:</strong> <code>Category_Device_Function</code> (ex: <code>M01_Pump_Running</code>)</li><li><strong>Kommentera:</strong> Alla taggar ska ha beskrivande kommentarer</li><li><strong>Organisation:</strong> Använd flera tag tables (ex: &quot;Inputs&quot;, &quot;Outputs&quot;, &quot;System&quot;)</li></ol></div><div class="warning custom-block"><p class="custom-block-title">OBS</p><p>Överanvänd inte globala taggar - det leder till spagettikod där allt kan ändra allt. Använd FB-instanser och parametrar för strukturerad kommunikation.</p></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/document/109746530/working-with-tags-in-tia-portal" target="_blank" rel="noreferrer">Siemens: Working with Tags (PDF)</a></li><li><a href="https://www.youtube.com/watch?v=qb7-gQzZXMQ" target="_blank" rel="noreferrer">Video: PLC Tags vs Local Variables</a></li><li><a href="./datatyper.html">Nästa: Datatyper och DB →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./datatyper.html">Datatyper i TIA Portal</a></li><li><a href="./koppling-plc-hmi.html">Koppling mellan PLC och HMI</a></li><li><a href="./../04-programmering/ob-fb-fc.html">Programmering med FB och FC</a></li></ul>`,55)])])}const u=t(l,[["render",r]]);export{h as __pageData,u as default};
